struct Noisy(&'static str);

impl Drop for Noisy {
    fn drop(&mut self) {
        println!("drop {}", self.0);
    }
}

struct Pair {
    left: Noisy,
    right: Noisy,
}

fn make_buffers() {
    let _first = Noisy("first");
    let _second = Noisy("second");
    let _pair = Pair { left: Noisy("pair.left"), right: Noisy("pair.right") };
    println!("leaving make_buffers");
}

fn main() {
    make_buffers();
    let early = Noisy("early");
    drop(early);
    println!("end of main");
}

